// Ayarlar › Açık kaynak lisansları, opened as a full-screen sheet from Settings (not a route, so it needs no
// entry in the root layout's sign-in groups): the runtime libraries with their declared licenses and the bundled
// font's SIL Open Font License text, and the pictures others made (data/art-licenses). The library list is
// generated by scripts/licenses.mjs (data/licenses.ts).
import { Fragment, useState } from 'react';
import { Linking, Modal, Pressable, ScrollView } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { Text } from '@/components/text';
import { ListBlock, ListGroup, ListRow } from '@/components/list';
import { Header } from '@/components/ui';
import { ART_LICENSES } from '@/data/art-licenses';
import { FONT_LICENSE, LICENSES } from '@/data/licenses';
import { makeStyles, useTheme } from '@/theme';

export function LicensesSheet({ visible, onClose }: { visible: boolean; onClose: () => void }) {
  const [showFont, setShowFont] = useState(false);
  const [showArt, setShowArt] = useState<string | null>(null);
  const { colors } = useTheme();
  const styles = useStyles();

  return (
    <Modal visible={visible} animationType="slide" onRequestClose={onClose}>
    <SafeAreaView style={{ flex: 1, backgroundColor: colors.bg }}>
      <Header title="Açık kaynak lisansları" onBack={onClose} />
      <ScrollView contentContainerStyle={styles.page}>
        <Text style={styles.intro}>Similar Club aşağıdaki açık kaynak yazılımlarla yapıldı. Her paket kendi lisansıyla dağıtılır; ayrıntı için pakete dokun.</Text>

        <ListGroup label="Yazı tipi" footer={`${FONT_LICENSE.copyright}. ${FONT_LICENSE.license} ile kullanılır.`}>
          <ListRow icon="text-outline" tone="neutral" title={FONT_LICENSE.family} subtitle={FONT_LICENSE.license} />
          <ListBlock>
            <Pressable onPress={() => setShowFont((v) => !v)} accessibilityRole="button" accessibilityState={{ expanded: showFont }}>
              <Text style={styles.toggle}>{showFont ? 'Lisans metnini gizle' : 'Lisans metnini göster'}</Text>
            </Pressable>
            {showFont && <Text style={styles.licenseText}>{FONT_LICENSE.text}</Text>}
          </ListBlock>
        </ListGroup>

        <ListGroup label="Görseller">
          {ART_LICENSES.map((a) => (
            <Fragment key={a.name}>
              <ListRow icon="happy-outline" tone="neutral" title={a.name} subtitle={`${a.source} · ${a.license}`} onPress={() => Linking.openURL(a.url)} accessibilityLabel={`${a.name}, ${a.source}, lisans ${a.license}`} />
              <ListBlock>
                <Pressable onPress={() => setShowArt((v) => (v === a.name ? null : a.name))} accessibilityRole="button" accessibilityState={{ expanded: showArt === a.name }}>
                  <Text style={styles.toggle}>{showArt === a.name ? 'Lisans metnini gizle' : 'Lisans metnini göster'}</Text>
                </Pressable>
                {showArt === a.name && <Text style={styles.licenseText}>{a.text}</Text>}
              </ListBlock>
            </Fragment>
          ))}
        </ListGroup>

        <ListGroup label={`Kütüphaneler (${LICENSES.length})`}>
          {LICENSES.map(({ name, version, license, url }) => (
            <ListRow
              key={name}
              title={name}
              subtitle={`${version} · ${license}`}
              onPress={url ? () => Linking.openURL(url) : undefined}
              accessibilityLabel={`${name}, sürüm ${version}, lisans ${license}`}
            />
          ))}
        </ListGroup>
      </ScrollView>
    </SafeAreaView>
    </Modal>
  );
}

const useStyles = makeStyles(({ colors, semantic }) => ({
  page: { paddingHorizontal: 16, paddingTop: 8, paddingBottom: 48, gap: 22 },
  intro: { color: colors.textDim, fontSize: 13, lineHeight: 19, paddingHorizontal: 4 },
  toggle: { color: semantic.tonalText, fontWeight: '700', fontSize: 14, paddingVertical: 4 },
  licenseText: { color: colors.textDim, fontSize: 12, lineHeight: 17, marginTop: 8 },
}));
